drop policy if exists session_meta_user_all on catalog.session_meta;
create policy session_meta_user_all on catalog.session_meta for all to catalog_user using (exists (select 1 from catalog.sessions s where s.id = session_id and s.show_id in (select catalog.accessible_shows(catalog.app_user_id())))) with check (exists (select 1 from catalog.sessions s where s.id = session_id and s.show_id in (select catalog.accessible_shows(catalog.app_user_id()))));
drop policy if exists session_events_user_all on catalog.session_events;
create policy session_events_user_all on catalog.session_events for all to catalog_user using (exists (select 1 from catalog.sessions s where s.id = session_id and s.show_id in (select catalog.accessible_shows(catalog.app_user_id())))) with check (exists (select 1 from catalog.sessions s where s.id = session_id and s.show_id in (select catalog.accessible_shows(catalog.app_user_id()))));
